//! `TunedValues`: eval values read from phased `(mg, eg)` weights per feature (see `layout`).
//!
//! `from_params` builds values that reproduce a `CdceParams` term for term. The equivalence test uses it
//! to check the index mapping against the hand-written `CdceParams` impl. `TunedValues::tuned()`
//! loads the weights generated by `cdce-tune` (`tuned_weights`).

use gears::games::chess::pieces::PieceType;
use gears::score::{p, PhasedScore, Score, ScoreT};

use crate::layout::{self, NUM_FEATURES};
use crate::params::CdceParams;
use crate::values::CdceValues;

#[derive(Debug, Clone)]
pub struct TunedValues {
    /// Middlegame weight per feature, centipawns.
    pub mg: [i32; NUM_FEATURES],
    /// Endgame weight per feature, centipawns.
    pub eg: [i32; NUM_FEATURES],
    pub rook_pawn_phase_gate: isize,
    pub tempo: i32,
}

impl TunedValues {
    /// Engine values from the fitted weights in `tuned_weights`. `rook_pawn_phase_gate` and `tempo` are not fitted
    /// (the tuner's trace has no tempo term), so they are taken from `CdceParams::default()`.
    pub fn tuned() -> Self {
        let base = CdceParams::default();
        Self {
            mg: crate::tuned_weights::MG,
            eg: crate::tuned_weights::EG,
            rook_pawn_phase_gate: base.rook_pawn_phase_gate as isize,
            tempo: base.tempo,
        }
    }

    /// Values equal to `params`, term for term. Terms that `CdceParams` maps to `p(v, 0)` are mg-only here.
    pub fn from_params(params: &CdceParams) -> Self {
        let mut v = Self {
            mg: [0; NUM_FEATURES],
            eg: [0; NUM_FEATURES],
            rook_pawn_phase_gate: params.rook_pawn_phase_gate as isize,
            tempo: params.tempo,
        };
        for (i, piece) in [PieceType::Pawn, PieceType::Knight, PieceType::Bishop, PieceType::Rook, PieceType::Queen]
            .into_iter()
            .enumerate()
        {
            v.both(layout::MATERIAL + i, params.piece_value(piece));
        }
        for a in 0..6 {
            for t in 0..6 {
                v.both(layout::ONE_WAY + a * 6 + t, params.ow_table[a][t]);
            }
        }
        v.both(layout::KNIGHT_FORK, params.fork_bonus);
        v.mg_only(layout::ROOK_OFF_HOME_RANK, params.rook_off_home_rank);
        v.mg_only(layout::ROOK_RANK3, params.rook_rank3);
        v.both(layout::ROOK_FILE_OPEN, params.rook_file_open);
        v.both(layout::ROOK_FILE_SEMI_OPEN, params.rook_file_semi_open);
        v.both(layout::ROOK_CONNECTED, params.rook_connected);
        v.mg_only(layout::ROOK_PAWN_GATE, params.rook_pawn_gate);
        for (i, val) in
            [params.mobility_knight, params.mobility_bishop, params.mobility_rook, params.mobility_queen].into_iter().enumerate()
        {
            v.both(layout::MOBILITY + i, val);
        }
        for (i, val) in [
            params.king_attacker_knight,
            params.king_attacker_bishop,
            params.king_attacker_rook,
            params.king_attacker_queen,
        ]
        .into_iter()
        .enumerate()
        {
            v.mg_only(layout::KING_ATTACKER + i, val);
        }
        v.mg_only(layout::KING_SHIELD, params.king_shield);
        v.both(layout::PAWN_DOUBLED, params.pawn_doubled);
        v.both(layout::PAWN_ISOLATED, params.pawn_isolated);
        for (r, val) in params.pawn_passed_rank.into_iter().enumerate() {
            v.both(layout::PAWN_PASSED + r, val);
        }
        v
    }

    fn both(&mut self, idx: usize, val: i32) {
        self.mg[idx] = val;
        self.eg[idx] = val;
    }

    fn mg_only(&mut self, idx: usize, val: i32) {
        self.mg[idx] = val;
    }

    #[inline]
    fn at(&self, idx: usize) -> PhasedScore {
        p(self.mg[idx] as i16, self.eg[idx] as i16)
    }
}

impl CdceValues for TunedValues {
    type Score = PhasedScore;
    const NAME_SUFFIX: &'static str = "-Tuned";

    #[inline]
    fn material(&self, piece: PieceType) -> PhasedScore {
        match piece {
            PieceType::Pawn | PieceType::Knight | PieceType::Bishop | PieceType::Rook | PieceType::Queen => {
                self.at(layout::MATERIAL + piece as usize)
            }
            _ => p(0, 0),
        }
    }

    #[inline]
    fn one_way(&self, attacker: PieceType, target: PieceType) -> PhasedScore {
        let (a, t) = (attacker as usize, target as usize);
        if a > 5 || t > 5 {
            return p(0, 0);
        }
        self.at(layout::ONE_WAY + a * 6 + t)
    }

    #[inline]
    fn knight_fork(&self) -> PhasedScore {
        self.at(layout::KNIGHT_FORK)
    }

    #[inline]
    fn rook_off_home_rank(&self) -> PhasedScore {
        self.at(layout::ROOK_OFF_HOME_RANK)
    }

    #[inline]
    fn rook_relative_rank3(&self) -> PhasedScore {
        self.at(layout::ROOK_RANK3)
    }

    #[inline]
    fn rook_file_open(&self) -> PhasedScore {
        self.at(layout::ROOK_FILE_OPEN)
    }

    #[inline]
    fn rook_file_semi_open(&self) -> PhasedScore {
        self.at(layout::ROOK_FILE_SEMI_OPEN)
    }

    #[inline]
    fn rook_connected(&self) -> PhasedScore {
        self.at(layout::ROOK_CONNECTED)
    }

    #[inline]
    fn rook_pawn_gate(&self) -> PhasedScore {
        self.at(layout::ROOK_PAWN_GATE)
    }

    #[inline]
    fn rook_pawn_phase_gate(&self) -> isize {
        self.rook_pawn_phase_gate
    }

    #[inline]
    fn mobility(&self, piece: PieceType) -> PhasedScore {
        layout::minor_major(piece).map_or(p(0, 0), |i| self.at(layout::MOBILITY + i))
    }

    #[inline]
    fn king_attacker(&self, attacker: PieceType) -> PhasedScore {
        layout::minor_major(attacker).map_or(p(0, 0), |i| self.at(layout::KING_ATTACKER + i))
    }

    #[inline]
    fn king_shield(&self) -> PhasedScore {
        self.at(layout::KING_SHIELD)
    }

    #[inline]
    fn pawn_doubled(&self) -> PhasedScore {
        self.at(layout::PAWN_DOUBLED)
    }

    #[inline]
    fn pawn_isolated(&self) -> PhasedScore {
        self.at(layout::PAWN_ISOLATED)
    }

    #[inline]
    fn pawn_passed(&self, relative_rank: usize) -> PhasedScore {
        if relative_rank < 8 {
            self.at(layout::PAWN_PASSED + relative_rank)
        } else {
            p(0, 0)
        }
    }

    #[inline]
    fn tempo(&self) -> Score {
        Score(self.tempo as ScoreT)
    }
}
